mkdir -p /out; cat > /tmp/c.py <<'E'
import json,csv
def bad(c): raise ValueError(c)
rows=[];errs=[]
data=open('/data/events.jsonl','rb').read().split(b'\n')
if data and data[-1]==b'': data.pop()
def flat(o,p,out):
    for k,v in o.items():
        key=p+k
        if isinstance(v,dict): flat(v,key+'.',out)
        else: out[key]=v
def cell(v):
    if v is None: return ''
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,str): return v
    if isinstance(v,list): return json.dumps(v,separators=(',',':'),ensure_ascii=False)
    return json.dumps(v)
for i,b in enumerate(data,1):
    try: s=b.decode('utf-8')
    except: errs.append(i); continue
    if not s.strip(): continue
    try: o=json.loads(s,parse_constant=bad)
    except Exception: errs.append(i); continue
    if not isinstance(o,dict): errs.append(i); continue
    d={}; flat(o,'',d); rows.append(d)
cols=sorted({k for r in rows for k in r})
with open('/out/events.csv','w',newline='',encoding='utf-8') as f:
    w=csv.writer(f,lineterminator='\n',quoting=csv.QUOTE_MINIMAL)
    w.writerow(cols)
    for r in rows: w.writerow([cell(r.get(c)) for c in cols])
open('/out/errors.txt','w').write(''.join(f'line {n}\n' for n in errs))
